      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "131I-MIP-1145, an anilide with a methoxy group and a basic tertiary-amine side chain closely resembling the query's aniline/methoxy/basic-amine motif, crossed the blood-brain barrier with 0.6-0.8 % ID/g brain uptake in mice.",
      "evidence_role": "supportive"
    },
    {
